// @generated by:gauntlet run:godseye-local-backend

import { truncate } from "node:fs/promises";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { committedFile } from "./backend-file-fixture.js";
import { type BackendFixture, backendFixture } from "./backend-fixture.js";

describe("private download handle lifetime and finite capacity", () => {
  let fixture: BackendFixture | undefined;
  afterEach(async () => fixture?.close());
  async function setup(lifetime = 1000) {
    fixture = await backendFixture({
      limits: { streamConnections: 1, streamPollMs: 10, streamLifetimeMs: lifetime },
    });
    const cookie = (await fixture.register()).cookie;
    const { file } = await committedFile(fixture, cookie);
    return { fixture, cookie, path: `/files/${file.id}/download` };
  }

  it("T-AC-57 T-AC-59 releases an unread download handle and slot when its finite lifetime expires", async () => {
    const { fixture, cookie, path } = await setup(100);
    const unread = await fixture.request(path, { headers: { cookie } });
    expect(unread.status).toBe(200);
    expect(fixture.runtime.state.downloads.size).toBe(1);
    expect((await fixture.request(path, { headers: { cookie } })).status).toBe(429);
    await new Promise((resolve) => setTimeout(resolve, 150));
    expect(fixture.runtime.state.downloads.size).toBe(0);
    expect(fixture.runtime.state.downloadClosers.size).toBe(0);
    const next = await fixture.request(path, { headers: { cookie } });
    expect(next.status).toBe(200);
    await unread.body?.cancel();
    await next.body?.cancel();
  });

  it("T-AC-57 T-AC-59 releases an unread download on request abort without a body read", async () => {
    const { fixture, cookie, path } = await setup();
    const abort = new AbortController();
    const unread = await fixture.request(path, { headers: { cookie }, signal: abort.signal });
    expect(unread.status).toBe(200);
    abort.abort();
    await new Promise((resolve) => setTimeout(resolve, 20));
    expect(fixture.runtime.state.downloads.size).toBe(0);
    expect(fixture.runtime.state.downloadClosers.size).toBe(0);
    const next = await fixture.request(path, { headers: { cookie } });
    expect(next.status).toBe(200);
    await unread.body?.cancel();
    await next.body?.cancel();
  });

  it("T-AC-57 T-AC-59 closes an unread download when its actual app session is revoked", async () => {
    const { fixture, cookie, path } = await setup();
    const unread = await fixture.request(path, { headers: { cookie } });
    expect(unread.status).toBe(200);
    expect((await fixture.json("/auth/sign-out", {}, { cookie })).status).toBe(200);
    await new Promise((resolve) => setTimeout(resolve, 50));
    expect(fixture.runtime.state.downloads.size).toBe(0);
    expect(fixture.runtime.state.downloadClosers.size).toBe(0);
    const reader = unread.body?.getReader();
    expect(await reader?.read()).toMatchObject({ done: true });
  });

  it("T-AC-59 drains real file handles before closing the application database", async () => {
    const { fixture, cookie, path } = await setup();
    const unread = await fixture.request(path, { headers: { cookie } });
    expect(unread.status).toBe(200);
    expect(fixture.runtime.state.downloads.size).toBe(1);
    await fixture.runtime.close();
    expect(fixture.runtime.state.downloads.size).toBe(0);
    expect(fixture.runtime.state.downloadClosers.size).toBe(0);
    expect(await unread.body?.getReader().read()).toMatchObject({ done: true });
  });

  it("T-AC-57 never leaks download capacity when actual object length differs from committed metadata", async () => {
    const { fixture, cookie, path } = await setup();
    const id = path.split("/")[2];
    if (!id) throw new Error("Synthetic file identifier absent");
    await truncate(join(fixture.filesRoot, id), 1);
    for (let attempt = 0; attempt < 3; attempt++) {
      const response = await fixture.request(path, { headers: { cookie } });
      expect(response.status).toBe(409);
      expect(fixture.runtime.state.downloads.size).toBe(0);
      expect(fixture.runtime.state.downloadClosers.size).toBe(0);
    }
  });

  it("T-AC-59 waits for a registered download close acknowledgement before completing runtime shutdown", async () => {
    const { fixture, cookie, path } = await setup();
    const unread = await fixture.request(path, { headers: { cookie } });
    expect(unread.status).toBe(200);
    const entry = [...fixture.runtime.state.downloadClosers][0];
    if (!entry) throw new Error("Actual download cleanup not registered");
    const [controller, actualClose] = entry;
    let acknowledge: (() => void) | undefined;
    const pending = new Promise<void>((resolve) => {
      acknowledge = resolve;
    });
    fixture.runtime.state.downloadClosers.set(controller, async () => {
      await pending;
      await actualClose();
    });
    let settled = false;
    const closing = fixture.runtime.close().then(() => {
      settled = true;
    });
    await new Promise((resolve) => setTimeout(resolve, 20));
    try {
      expect(settled).toBe(false);
    } finally {
      acknowledge?.();
    }
    await closing;
    expect(settled).toBe(true);
    expect(fixture.runtime.state.downloadClosers.size).toBe(0);
  });
});
